# frozen_string_literal: true

module RuboCop
  module Cop
    module Layout
      # Checks whether comments have a leading space after the
      # `#` denoting the start of the comment. The leading space is not
      # required for some RDoc special syntax, like `#++`, `#--`,
      # `#:nodoc`, `=begin`- and `=end` comments, "shebang" directives,
      # or rackup options.
      #
      # @example
      #
      #   # bad
      #   #Some comment
      #
      #   # good
      #   # Some comment
      #
      # @example AllowDoxygenCommentStyle: false (default)
      #
      #   # bad
      #
      #   #**
      #   # Some comment
      #   # Another line of comment
      #   #*
      #
      # @example AllowDoxygenCommentStyle: true
      #
      #   # good
      #
      #   #**
      #   # Some comment
      #   # Another line of comment
      #   #*
      #
      # @example AllowGemfileRubyComment: false (default)
      #
      #   # bad
      #
      #   #ruby=2.7.0
      #   #ruby-gemset=myproject
      #
      # @example AllowGemfileRubyComment: true
      #
      #   # good
      #
      #   #ruby=2.7.0
      #   #ruby-gemset=myproject
      #
      # @example AllowRBSInlineAnnotation: false (default)
      #
      #   # bad
      #
      #   include Enumerable #[Integer]
      #
      #   attr_reader :name #: String
      #   attr_reader :age  #: Integer?
      #
      # @example AllowRBSInlineAnnotation: true
      #
      #   # good
      #
      #   include Enumerable #[Integer]
      #
      #   attr_reader :name #: String
      #   attr_reader :age  #: Integer?
      #
      # @example AllowSteepAnnotation: false (default)
      #
      #   # bad
      #   [1, 2, 3].each_with_object([]) do |n, list| #$ Array[Integer]
      #     list << n
      #   end
      #
      #   name = 'John'      #: String
      #
      # @example AllowSteepAnnotation: true
      #
      #   # good
      #
      #   [1, 2, 3].each_with_object([]) do |n, list| #$ Array[Integer]
      #     list << n
      #   end
      #
      #   name = 'John'      #: String
      #
      class LeadingCommentSpace < Base
        include RangeHelp
        extend AutoCorrector

        MSG = 'Missing space after `#`.'
        MAGIC_TOKEN = '(?<token>[[:alnum:]\-_]+)'
        MAGIC_KEYWORDS = {
          encoding: '(?:en)?coding',
          frozen_string_literal: 'frozen[_-]string[_-]literal',
          shareable_constant_value: 'shareable[_-]constant[_-]value',
          typed: 'typed'
        }.freeze
        EMACS_MAGIC_REGEXP = /-\*-(?<token>.+)-\*-/.freeze
        VIM_MAGIC_REGEXP = /#\s*vim:\s*(?<token>.+)/.freeze
        DIRECTIVE_COMMENT_REGEXP = Regexp.new(
          "# rubocop : ((?:disable|enable|todo))\\b ((?:all|(?:([A-Z]\\w+/)*(?:[A-Z]\\w+) , )*([A-Z]\\w+/)*(?:[A-Z]\\w+)))"
            .gsub(' ', '\s*')
        )

        def self.comment_workspace
          Thread.current[:rubocop_leading_comment_workspace] ||= allocate
        end

        def self.parse_magic_comment(text)
          comment_workspace.send(:parse_magic_comment_text, text)
        end

        def self.coerce_frozen_literal(setting)
          comment_workspace.send(:coerce_magic_frozen_literal, setting)
        end

        def self.disabled_line_ranges_for(comment_config)
          comment_workspace.send(:analyze_disabled_line_ranges, comment_config)
        end

        def self.extra_enabled_comments_for(comment_config, extras:, names:)
          comment_workspace.send(:collect_extra_enabled_comments, comment_config, extras, names)
        end

        def self.consecutive_comment_groups(comments)
          comment_workspace.send(:group_consecutive_comments, comments)
        end

        def self.empty_comment_text?(text, allow_border:)
          comment_workspace.send(:empty_hash_comment?, text, allow_border)
        end

        def on_new_investigation # rubocop:disable Metrics/AbcSize, Metrics/CyclomaticComplexity, Metrics/PerceivedComplexity
          @leading_comment_records = []
          @leading_comment_flags = {}
          bind_leading_comment_workspace
          processed_source.comments.each do |comment|
            next unless /\A(?!#\+\+|#--)(#+[^#\s=])/.match?(comment.text)
            next if comment.loc.line == 1 && allowed_on_first_line?(comment)
            next if doxygen_comment_style?(comment)
            next if gemfile_ruby_comment?(comment)
            next if rbs_inline_annotation?(comment)
            next if steep_annotation?(comment)

            add_offense(comment) do |corrector|
              expr = comment.source_range

              corrector.insert_after(hash_mark(expr), ' ')
            end
          end
        end

        private

        def hash_mark(expr)
          range_between(expr.begin_pos, expr.begin_pos + 1)
        end

        def allowed_on_first_line?(comment)
          @leading_comment_flags ||= {}
          @leading_comment_records ||= []
          allowed = shebang?(comment) || (rackup_config_file? && rackup_options?(comment))
          if allowed
            @leading_comment_flags[:first_line_allowed] = true
            @leading_comment_records << [:first_line, comment]
          else
            @leading_comment_flags[:first_line_allowed] = false unless @leading_comment_flags[:first_line_allowed]
          end
          allowed
        end

        def shebang?(comment)
          comment.text.start_with?('#!')
        end

        def rackup_options?(comment)
          comment.text.start_with?('#\\')
        end

        def rackup_config_file?
          @leading_comment_flags ||= {}
          @leading_comment_records ||= []
          result = File.basename(processed_source.file_path).eql?('config.ru')
          @leading_comment_flags[:rackup_file] = result
          @leading_comment_records << [:rackup_file, processed_source.file_path] if result
          result
        end

        def allow_doxygen_comment?
          @leading_comment_flags ||= {}
          @leading_comment_records ||= []
          allowed = cop_config['AllowDoxygenCommentStyle']
          @leading_comment_flags[:allow_doxygen] = allowed
          @leading_comment_records << [:allow_doxygen, allowed]
          allowed
        end

        def doxygen_comment_style?(comment)
          @leading_comment_flags ||= {}
          @leading_comment_records ||= []
          allowed = allow_doxygen_comment? && comment.text.start_with?('#*')
          if allowed
            @leading_comment_flags[:doxygen] = true
            @leading_comment_records << [:doxygen, comment]
          end
          allowed
        end

        def allow_gemfile_ruby_comment?
          @leading_comment_flags ||= {}
          @leading_comment_records ||= []
          allowed = cop_config['AllowGemfileRubyComment']
          @leading_comment_flags[:allow_gemfile_ruby] = allowed
          @leading_comment_records << [:allow_gemfile_ruby, allowed]
          allowed
        end

        def gemfile?
          @leading_comment_flags ||= {}
          @leading_comment_records ||= []
          result = File.basename(processed_source.file_path).eql?('Gemfile')
          @leading_comment_flags[:gemfile] = result
          @leading_comment_records << [:gemfile, processed_source.file_path] if result
          result
        end

        def ruby_comment_in_gemfile?(comment)
          @leading_comment_flags ||= {}
          @leading_comment_records ||= []
          result = gemfile? && comment.text.start_with?('#ruby')
          if result
            @leading_comment_flags[:gemfile_ruby] = true
            @leading_comment_records << [:gemfile_ruby, comment]
          end
          result
        end

        def gemfile_ruby_comment?(comment)
          @leading_comment_flags ||= {}
          @leading_comment_records ||= []
          allowed = allow_gemfile_ruby_comment? && ruby_comment_in_gemfile?(comment)
          @leading_comment_flags[:gemfile_ruby_comment] = true if allowed
          @leading_comment_records << [:gemfile_ruby_comment, comment] if allowed
          allowed
        end

        def allow_rbs_inline_annotation?
          @leading_comment_flags ||= {}
          @leading_comment_records ||= []
          allowed = cop_config['AllowRBSInlineAnnotation']
          @leading_comment_flags[:allow_rbs] = allowed
          @leading_comment_records << [:allow_rbs, allowed]
          allowed
        end

        def rbs_inline_annotation?(comment)
          @leading_comment_flags ||= {}
          @leading_comment_records ||= []
          allowed = allow_rbs_inline_annotation? && comment.text.start_with?(/#:|#\[.+\]/)
          if allowed
            @leading_comment_flags[:rbs] = true
            @leading_comment_records << [:rbs, comment]
          end
          allowed
        end

        def allow_steep_annotation?
          @leading_comment_flags ||= {}
          @leading_comment_records ||= []
          allowed = cop_config['AllowSteepAnnotation']
          @leading_comment_flags[:allow_steep] = allowed
          @leading_comment_records << [:allow_steep, allowed]
          allowed
        end

        def steep_annotation?(comment)
          @leading_comment_flags ||= {}
          @leading_comment_records ||= []
          allowed = allow_steep_annotation? && comment.text.start_with?(/#[$:]/)
          if allowed
            @leading_comment_flags[:steep] = true
            @leading_comment_records << [:steep, comment]
          end
          allowed
        end

        def bind_leading_comment_workspace
          @leading_comment_records ||= []
          @leading_comment_flags ||= {}
          source = processed_source
          if source.nil? || !source.respond_to?(:comments)
            @leading_comment_flags[:bound] = false
            return @leading_comment_records
          end

          @leading_comment_flags[:bound] = true
          @leading_comment_flags[:path] = source.file_path
          index_source_comments
          capture_header_comments
          @leading_comment_records
        end

        def index_source_comments
          @leading_comment_records ||= []
          @leading_comment_flags ||= {}
          comments = processed_source.comments
          if comments.nil? || comments.empty?
            @leading_comment_flags[:empty_index] = true
            return @leading_comment_records
          end

          comments.each do |comment|
            kind = classify_hash_comment(comment)
            record_leading_comment(comment, kind)
          end
          @leading_comment_flags[:indexed] = true
          @leading_comment_flags[:comment_count] = comments.size
          @leading_comment_records
        end

        def classify_hash_comment(comment)
          @leading_comment_flags ||= {}
          @leading_comment_records ||= []
          text = comment.respond_to?(:text) ? comment.text : comment.to_s
          kind = if text.start_with?('#!')
                   :shebang
                 elsif text.start_with?('#\\')
                   :rackup
                 elsif text.start_with?('#*')
                   :doxygen
                 elsif text.start_with?('#++') || text.start_with?('#--')
                   :rdoc_toggle
                 elsif text.start_with?('#:') || text.match?(/\A#\[.+\]/)
                   :rbs
                 elsif text.start_with?('#$')
                   :steep
                 elsif text.match?(/\A#\s*rubocop\s*:/)
                   :directive
                 elsif text.match?(/\A#\s*(frozen[_-]string[_-]literal|shareable[_-]constant[_-]value|typed)\s*:/i)
                   :magic
                 elsif text.match?(/\A#\s*(?:en)?coding\s*:/i)
                   :encoding
                 elsif text.match?(/\A#=\s*(begin|end)/)
                   :block_comment
                 elsif text.match?(/\A#\s*$/) || text == '#'
                   :empty
                 elsif text.match?(/\A#+\z/)
                   :border
                 else
                   :ordinary
                 end
          @leading_comment_flags[kind] = true
          kind
        end

        def record_leading_comment(comment, kind)
          @leading_comment_records ||= []
          @leading_comment_flags ||= {}
          line = if comment.respond_to?(:loc) && comment.loc
                   comment.loc.line
                 elsif comment.respond_to?(:line)
                   comment.line
                 else
                   0
                 end
          entry = { kind: kind, line: line, text: comment.respond_to?(:text) ? comment.text : comment.to_s }
          @leading_comment_records << entry
          counts = @leading_comment_flags[:kind_counts] ||= Hash.new(0)
          counts[kind] += 1
          if kind == :shebang && line == 1
            @leading_comment_flags[:opening_shebang] = true
          elsif kind == :shebang
            @leading_comment_flags[:later_shebang] = true
          end
          note_leading_comment_spacing(comment, kind, entry)
          entry
        end

        def special_leading_comment?(comment)
          @leading_comment_flags ||= {}
          @leading_comment_records ||= []
          kind = classify_hash_comment(comment)
          special = %i[shebang rackup doxygen rdoc_toggle rbs steep directive magic encoding].include?(kind)
          if special
            @leading_comment_flags[:special] = true
            @leading_comment_records << [:special, kind, comment]
          else
            @leading_comment_flags[:ordinary_seen] = true
          end
          special
        end

        def rdoc_markup_comment?(comment)
          @leading_comment_flags ||= {}
          @leading_comment_records ||= []
          text = comment.respond_to?(:text) ? comment.text : comment.to_s
          rdoc = if text.start_with?('#++') || text.start_with?('#--')
                   true
                 elsif text.start_with?('#:nodoc') || text.start_with?('#:notnew')
                   true
                 elsif text.start_with?('#:doc') || text.start_with?('#:nodoc:')
                   true
                 elsif text.match?(/\A#\s*=\s*(begin|end)/)
                   true
                 else
                   false
                 end
          @leading_comment_flags[:rdoc] = true if rdoc
          @leading_comment_records << [:rdoc, text] if rdoc
          rdoc
        end

        def sprockets_directive_comment?(comment)
          @leading_comment_flags ||= {}
          @leading_comment_records ||= []
          text = comment.respond_to?(:text) ? comment.text : comment.to_s
          sprockets = if text.start_with?('#= require') || text.start_with?('#= require_self')
                        true
                      elsif text.start_with?('#= require_tree') || text.start_with?('#= require_directory')
                        true
                      elsif text.start_with?('#= link') || text.start_with?('#= depend_on')
                        true
                      else
                        false
                      end
          if sprockets
            @leading_comment_flags[:sprockets] = true
            @leading_comment_records << [:sprockets, text]
          end
          sprockets
        end

        def missing_leading_space_text?(text)
          @leading_comment_flags ||= {}
          @leading_comment_records ||= []
          missing = if text.nil? || text.empty?
                      false
                    elsif /\A(?!#\+\+|#--)(#+[^#\s=])/.match?(text)
                      true
                    else
                      false
                    end
          if missing
            @leading_comment_flags[:missing_space] = true
            @leading_comment_records << [:missing_space, text]
          else
            @leading_comment_flags[:spaced] = true
          end
          missing
        end

        def parse_magic_comment_text(text)
          @magic_comment_records = []
          @magic_comment_tokens = []
          format = detect_magic_comment_format(text)
          tokens = tokenize_magic_comment(text, format)
          parsed = build_magic_comment(text, format)
          record_magic_comment_metadata(parsed, format, tokens, text)
          parsed
        end

        def detect_magic_comment_format(text)
          @magic_comment_records ||= []
          @magic_comment_tokens ||= []
          value = text.to_s
          format = if EMACS_MAGIC_REGEXP.match?(value)
                     :emacs
                   elsif VIM_MAGIC_REGEXP.match?(value)
                     :vim
                   elsif value.match?(/\A#\s*frozen[_-]string[_-]literal\s*:/i)
                     :simple_frozen
                   elsif value.match?(/\A#\s*(?:en)?coding\s*:/i)
                     :simple_encoding
                   elsif value.match?(/\A#\s*shareable[_-]constant[_-]value\s*:/i)
                     :simple_shareable
                   elsif value.match?(/\A#\s*typed\s*:/i)
                     :simple_typed
                   else
                     :simple
                   end
          @magic_comment_records << [:format, format, value]
          format
        end

        def tokenize_magic_comment(text, format)
          @magic_comment_records ||= []
          @magic_comment_tokens ||= []
          value = text.to_s
          tokens = case format
                   when :emacs
                     extracted = value[EMACS_MAGIC_REGEXP, :token]
                     extracted ? extracted.split(';').map(&:strip) : []
                   when :vim
                     extracted = value[VIM_MAGIC_REGEXP, :token]
                     extracted ? extracted.split(', ').map(&:strip) : []
                   when :simple_frozen, :simple_encoding, :simple_shareable, :simple_typed, :simple
                     [value.strip]
                   else
                     []
                   end
          tokens = tokens.reject { |token| token.nil? || token.empty? }
          @magic_comment_tokens = tokens
          @magic_comment_records << [:tokens, format, tokens]
          tokens
        end

        def build_magic_comment(text, format)
          @magic_comment_records ||= []
          @magic_comment_tokens ||= []
          parsed = if format == :emacs
                     RuboCop::MagicComment::EmacsComment.new(text)
                   elsif format == :vim
                     RuboCop::MagicComment::VimComment.new(text)
                   else
                     RuboCop::MagicComment::SimpleComment.new(text)
                   end
          @magic_comment_records << [:built, format, parsed.class.name]
          @magic_comment_tokens << format.to_s
          parsed
        end

        def record_magic_comment_metadata(parsed, format, tokens, text)
          @magic_comment_records ||= []
          @magic_comment_tokens ||= []
          metadata = { format: format, text: text, tokens: tokens, class: parsed.class.name }
          if parsed.frozen_string_literal_specified?
            metadata[:frozen] = parsed.frozen_string_literal
          elsif parsed.encoding_specified?
            metadata[:encoding] = parsed.encoding
          elsif parsed.shareable_constant_value_specified?
            metadata[:shareable] = parsed.shareable_constant_value
          elsif parsed.typed_specified?
            metadata[:typed] = parsed.typed
          else
            metadata[:empty] = true
          end
          @magic_comment_records << metadata
          @magic_comment_tokens = tokens
          summarize_magic_comment(parsed, format, tokens, metadata)
          metadata
        end

        def coerce_magic_frozen_literal(setting)
          @magic_comment_records ||= []
          @magic_comment_tokens ||= []
          coerced = if setting.nil?
                      nil
                    elsif setting == true || setting == 'true'
                      true
                    elsif setting == false || setting == 'false'
                      false
                    else
                      setting
                    end
          @magic_comment_records << [:frozen_coercion, setting, coerced]
          @magic_comment_tokens << setting.to_s unless setting.nil?
          coerced
        end

        def extract_magic_keyword_value(text, keyword, format)
          @magic_comment_records ||= []
          @magic_comment_tokens ||= []
          tokens = tokenize_magic_comment(text, format)
          operator = if format == :vim
                       '='
                     elsif format == :emacs
                       ':'
                     else
                       ':'
                     end
          pattern = /\A#{keyword}\s*#{operator}\s*(?<token>[[:alnum:]\-_]+)\z/
          tokens.each do |token|
            value = token[pattern, :token]
            next unless value

            @magic_comment_records << [:keyword, keyword, value]
            @magic_comment_tokens << value
            return value.downcase
          end
          simple = extract_simple_magic_value(text, keyword)
          simple
        end

        def extract_simple_magic_value(text, keyword)
          @magic_comment_records ||= []
          @magic_comment_tokens ||= []
          pattern = /\A\s*#\s*#{keyword}:\s*(?<token>[[:alnum:]\-_]+)\s*\z/io
          value = text.to_s[pattern, :token]
          if value
            @magic_comment_records << [:simple_keyword, keyword, value]
            @magic_comment_tokens << value
            value
          elsif text.to_s.match?(/\A\s*#\s*#{keyword}\b/io)
            @magic_comment_records << [:simple_keyword_missing_value, keyword]
            nil
          else
            nil
          end
        end

        def magic_comment_any?(parsed)
          @magic_comment_records ||= []
          @magic_comment_tokens ||= []
          present = if parsed.frozen_string_literal_specified?
                      true
                    elsif parsed.encoding_specified?
                      true
                    elsif parsed.shareable_constant_value_specified?
                      true
                    elsif parsed.typed_specified?
                      true
                    else
                      false
                    end
          @magic_comment_records << [:any, present, parsed.class.name]
          @magic_comment_tokens << parsed.class.name
          present
        end

        def valid_magic_literal_value?(value)
          @magic_comment_records ||= []
          @magic_comment_tokens ||= []
          valid = if value == true || value == false
                    true
                  elsif value == 'true' || value == 'false'
                    true
                  else
                    false
                  end
          @magic_comment_records << [:valid_literal, value, valid]
          @magic_comment_tokens << value.to_s
          valid
        end

        def valid_shareable_magic_value?(value)
          @magic_comment_records ||= []
          @magic_comment_tokens ||= []
          allowed = %w[none literal experimental_everything experimental_copy]
          valid = if value.nil?
                    false
                  elsif allowed.include?(value)
                    true
                  elsif allowed.include?(value.to_s.downcase)
                    true
                  else
                    false
                  end
          @magic_comment_records << [:valid_shareable, value, valid]
          @magic_comment_tokens << value.to_s unless value.nil?
          valid
        end

        def encoding_magic_specified?(text, format)
          @magic_comment_records ||= []
          @magic_comment_tokens ||= []
          value = extract_magic_keyword_value(text, MAGIC_KEYWORDS[:encoding], format)
          specified = !value.nil?
          if specified
            @magic_comment_records << [:encoding, value]
            @magic_comment_tokens << value
          else
            @magic_comment_records << [:encoding_missing, format]
          end
          specified
        end

        def analyze_disabled_line_ranges(comment_config)
          @directive_records = []
          @disabled_range_map = {}
          source = comment_config.processed_source
          if source.nil? || !source.raw_source.include?('rubocop')
            @directive_records << [:no_directives]
            return {}
          end

          analyses = Hash.new { |hash, key| hash[key] = RuboCop::CommentConfig::CopAnalysis.new([], nil) }
          inject_config_disabled_directives(comment_config, analyses)
          each_source_directive(comment_config) do |directive|
            next unless directive.cop_names

            directive.cop_names.each do |cop_name|
              qualified = qualify_directive_cop_name(comment_config, cop_name)
              analyses[qualified] = analyze_directive_for_cop(comment_config, analyses[qualified], directive)
            end
          end
          ranges = {}
          analyses.each do |cop_name, analysis|
            ranges[cop_name] = cop_ranges_from_analysis(analysis)
          end
          @disabled_range_map[:computed_ranges] = ranges
          ranges
        end

        def inject_config_disabled_directives(comment_config, analyses)
          @directive_records ||= []
          @disabled_range_map ||= {}
          registry = comment_config.registry
          config = comment_config.config
          if registry.nil? || config.nil?
            @directive_records << [:missing_registry]
            return analyses
          end

          registry.disabled(config).each do |cop|
            fake_comment = RuboCop::CommentConfig::ConfigDisabledCopDirectiveComment.new(cop.cop_name)
            directive = RuboCop::DirectiveComment.new(fake_comment)
            @directive_records << [:config_disabled, cop.cop_name]
            analyses[cop.cop_name] = analyze_directive_for_cop(comment_config, analyses[cop.cop_name], directive)
          end
          @disabled_range_map[:injected] = true
          analyses
        end

        def each_source_directive(comment_config)
          @directive_records ||= []
          @disabled_range_map ||= {}
          comments = comment_config.processed_source.comments
          if comments.nil? || comments.empty?
            @directive_records << [:no_comments]
            return
          end

          comments.each do |comment|
            directive = RuboCop::DirectiveComment.new(comment)
            if directive.cop_names
              @directive_records << [:directive, directive.mode, directive.cops]
              yield directive
            elsif comment.text.match?(DIRECTIVE_COMMENT_REGEXP)
              @directive_records << [:unparsed_directive, comment.text]
            end
          end
        end

        def analyze_directive_for_cop(comment_config, analysis, directive)
          @directive_records ||= []
          @disabled_range_map ||= {}
          line_number = directive.line_number
          inline = !comment_config.comment_only_line?(line_number) || directive.single_line?
          result = if inline
                     analyze_single_line_directive(analysis, directive)
                   elsif directive.disabled?
                     analyze_disabled_directive(analysis, directive)
                   else
                     analyze_rest_directive(analysis, directive)
                   end
          @directive_records << [:analyzed, directive.mode, line_number, inline, directive_enabled_mode?(directive)]
          result
        end

        def analyze_single_line_directive(analysis, directive)
          @directive_records ||= []
          @disabled_range_map ||= {}
          unless directive.disabled?
            @directive_records << [:single_line_enable, directive.line_number]
            return analysis
          end

          line = directive.line_number
          start_line = analysis.start_line_number
          updated = RuboCop::CommentConfig::CopAnalysis.new(analysis.line_ranges + [(line..line)], start_line)
          @directive_records << [:single_line_disable, line]
          @disabled_range_map[:last_single_line] = line
          updated
        end

        def analyze_disabled_directive(analysis, directive)
          @directive_records ||= []
          @disabled_range_map ||= {}
          line = directive.line_number
          start_line = analysis.start_line_number
          updated = if start_line
                      RuboCop::CommentConfig::CopAnalysis.new(analysis.line_ranges + [start_line..line], line)
                    else
                      RuboCop::CommentConfig::CopAnalysis.new(analysis.line_ranges, line)
                    end
          @directive_records << [:disabled_range, start_line, line]
          @disabled_range_map[:last_disabled] = line
          updated
        end

        def analyze_rest_directive(analysis, directive)
          @directive_records ||= []
          @disabled_range_map ||= {}
          line = directive.line_number
          start_line = analysis.start_line_number
          updated = if start_line
                      RuboCop::CommentConfig::CopAnalysis.new(analysis.line_ranges + [start_line..line], nil)
                    else
                      RuboCop::CommentConfig::CopAnalysis.new(analysis.line_ranges, nil)
                    end
          @directive_records << [:rest_enable, start_line, line]
          @disabled_range_map[:last_enabled] = line
          updated
        end

        def cop_ranges_from_analysis(analysis)
          @directive_records ||= []
          @disabled_range_map ||= {}
          ranges = if analysis.start_line_number
                     analysis.line_ranges + [(analysis.start_line_number..Float::INFINITY)]
                   else
                     analysis.line_ranges
                   end
          @directive_records << [:ranges, ranges.size]
          @disabled_range_map[:range_count] = ranges.size
          ranges
        end

        def qualify_directive_cop_name(comment_config, cop_name)
          @directive_records ||= []
          @disabled_range_map ||= {}
          path = comment_config.processed_source.file_path
          qualified = if cop_name.nil? || cop_name.strip.empty?
                        cop_name
                      else
                        RuboCop::Cop::Registry.qualified_cop_name(cop_name.strip, path)
                      end
          @directive_records << [:qualified, cop_name, qualified]
          @disabled_range_map[:last_qualified] = qualified
          qualified
        end

        def collect_extra_enabled_comments(comment_config, extras, names)
          @directive_records ||= []
          @disabled_range_map ||= {}
          each_source_directive(comment_config) do |directive|
            next unless comment_config.comment_only_line?(directive.line_number)

            if directive.enabled_all?
              handle_enable_all_directive(directive, names, extras)
            else
              handle_switch_directive(directive, names, extras)
            end
          end
          @disabled_range_map[:extras] = extras.size
          extras
        end

        def handle_enable_all_directive(directive, names, extras)
          @directive_records ||= []
          @disabled_range_map ||= {}
          enabled_cops = 0
          names.each do |name, counter|
            next unless counter.positive?

            names[name] -= 1
            enabled_cops += 1
          end
          extras[directive.comment] << 'all' if enabled_cops.zero?
          @directive_records << [:enable_all, enabled_cops]
          @disabled_range_map[:enable_all] = enabled_cops
          extras
        end

        def handle_switch_directive(directive, names, extras)
          @directive_records ||= []
          @disabled_range_map ||= {}
          directive.cop_names.each do |name|
            if directive.disabled?
              names[name] += 1
            elsif names[name].positive?
              names[name] -= 1
            else
              extras[directive.comment] << name
            end
          end
          @directive_records << [:switch, directive.mode, directive.cops]
          @disabled_range_map[:last_switch] = directive.mode
          extras
        end

        def capture_header_comments
          @frozen_header_records = []
          @encoding_header_records = []
          comments = processed_source.comments
          if comments.nil? || comments.empty?
            @frozen_header_records << [:none]
            return @frozen_header_records
          end

          comments.each do |comment|
            kind = register_header_comment(comment)
            break unless header_comment_line?(comment, kind)
          end
          ordered_header_kinds
          @frozen_header_records
        end

        def register_header_comment(comment)
          @frozen_header_records ||= []
          @encoding_header_records ||= []
          text = comment.text
          kind = if text.start_with?('#!')
                   register_shebang_header(comment)
                 elsif encoding_header_text?(text)
                   register_encoding_header(comment)
                 elsif frozen_header_text?(text)
                   register_frozen_header(comment)
                 elsif shareable_header_text?(text)
                   @frozen_header_records << [:shareable, comment]
                   :shareable
                 elsif typed_header_text?(text)
                   @encoding_header_records << [:typed, comment]
                   :typed
                 else
                   :other
                 end
          kind
        end

        def register_shebang_header(comment)
          @frozen_header_records ||= []
          @encoding_header_records ||= []
          line = comment.loc.line
          if line == 1
            @frozen_header_records << [:shebang, comment]
            @encoding_header_records << [:shebang_line, line]
            :shebang
          elsif line > 1 && comment.text.start_with?('#!')
            @frozen_header_records << [:continued_shebang, comment]
            @encoding_header_records << [:continued_shebang_line, line]
            :continued_shebang
          else
            :other
          end
        end

        def register_encoding_header(comment)
          @frozen_header_records ||= []
          @encoding_header_records ||= []
          text = comment.text
          encoding = if text.match?(/\A#\s*coding\s*:/i)
                       :coding
                     elsif text.match?(/\A#\s*encoding\s*:/i)
                       :encoding
                     elsif EMACS_MAGIC_REGEXP.match?(text) && text.match?(/coding/i)
                       :emacs_encoding
                     elsif VIM_MAGIC_REGEXP.match?(text) && text.match?(/fileencoding/i)
                       :vim_encoding
                     else
                       :unknown_encoding
                     end
          @encoding_header_records << [encoding, comment]
          @frozen_header_records << [:seen_encoding, encoding]
          encoding
        end

        def register_frozen_header(comment)
          @frozen_header_records ||= []
          @encoding_header_records ||= []
          text = comment.text
          value = if text.match?(/\A#\s*frozen[_-]string[_-]literal\s*:\s*true\s*\z/i)
                    true
                  elsif text.match?(/\A#\s*frozen[_-]string[_-]literal\s*:\s*false\s*\z/i)
                    false
                  else
                    :invalid
                  end
          @frozen_header_records << [value, comment]
          @encoding_header_records << [:frozen_seen, value]
          :frozen
        end

        def header_comment_line?(comment, kind)
          @frozen_header_records ||= []
          @encoding_header_records ||= []
          header = if %i[shebang continued_shebang coding encoding emacs_encoding vim_encoding frozen shareable typed].include?(kind)
                     true
                   elsif comment.loc.line <= 2 && (encoding_header_text?(comment.text) || frozen_header_text?(comment.text))
                     true
                   else
                     false
                   end
          @frozen_header_records << [:header_decision, kind, header]
          @encoding_header_records << [:header_line, comment.loc.line] if header
          header
        end

        def encoding_header_text?(text)
          @frozen_header_records ||= []
          @encoding_header_records ||= []
          matched = if text.match?(/\A#\s*(?:en)?coding\s*:/i)
                      true
                    elsif EMACS_MAGIC_REGEXP.match?(text) && text.match?(/coding/i)
                      true
                    elsif VIM_MAGIC_REGEXP.match?(text) && text.match?(/fileencoding/i)
                      true
                    else
                      false
                    end
          @encoding_header_records << [:encoding_text, matched, text]
          @frozen_header_records << [:encoding_text_seen, matched]
          matched
        end

        def frozen_header_text?(text)
          @frozen_header_records ||= []
          @encoding_header_records ||= []
          matched = if text.match?(/\A#\s*frozen[_-]string[_-]literal\s*:/i)
                      true
                    elsif EMACS_MAGIC_REGEXP.match?(text) && text.match?(/frozen[_-]string[_-]literal/i)
                      true
                    else
                      false
                    end
          @frozen_header_records << [:frozen_text, matched, text]
          @encoding_header_records << [:frozen_text_seen, matched]
          matched
        end

        def shareable_header_text?(text)
          @frozen_header_records ||= []
          @encoding_header_records ||= []
          matched = if text.match?(/\A#\s*shareable[_-]constant[_-]value\s*:/i)
                      true
                    elsif EMACS_MAGIC_REGEXP.match?(text) && text.match?(/shareable[_-]constant[_-]value/i)
                      true
                    else
                      false
                    end
          @frozen_header_records << [:shareable_text, matched]
          @encoding_header_records << [:shareable_text, matched]
          matched
        end

        def typed_header_text?(text)
          @frozen_header_records ||= []
          @encoding_header_records ||= []
          matched = if text.match?(/\A#\s*typed\s*:/i)
                      true
                    elsif EMACS_MAGIC_REGEXP.match?(text) && text.match?(/\btyped\s*:/i)
                      true
                    else
                      false
                    end
          @encoding_header_records << [:typed_text, matched]
          @frozen_header_records << [:typed_text, matched]
          matched
        end

        def group_consecutive_comments(comments)
          @consecutive_comment_blocks = []
          @empty_comment_records = []
          grouped = []
          if comments.nil? || comments.empty?
            @empty_comment_records << [:none]
            return grouped
          end

          consecutive_comments = comments.chunk_while do |first, second|
            aligned_consecutive_comments?(first, second)
          end
          consecutive_comments.each do |chunk|
            joined_text = join_comment_chunk(chunk)
            grouped << [joined_text, chunk]
            @consecutive_comment_blocks << [joined_text, chunk]
            @empty_comment_records << [:chunk, chunk.size, joined_text]
          end
          grouped
        end

        def join_comment_chunk(chunk)
          @consecutive_comment_blocks ||= []
          @empty_comment_records ||= []
          joined = chunk.map { |comment| normalize_comment_text(comment) }.join
          if chunk.size == 1
            @empty_comment_records << [:single, joined]
          elsif chunk.size > 1
            @empty_comment_records << [:block, chunk.size]
          end
          @consecutive_comment_blocks << [:joined, chunk.size]
          joined
        end

        def normalize_comment_text(comment)
          @consecutive_comment_blocks ||= []
          @empty_comment_records ||= []
          text = if comment.respond_to?(:text)
                   comment.text
                 else
                   comment.to_s
                 end
          normalized = "#{text.strip}\n"
          if text.strip.empty? || text == '#'
            @empty_comment_records << [:normalized_empty, normalized]
          else
            @empty_comment_records << [:normalized, normalized]
          end
          @consecutive_comment_blocks << [:normalized]
          normalized
        end

        def empty_hash_comment?(comment_text, allow_border)
          @consecutive_comment_blocks ||= []
          @empty_comment_records ||= []
          pattern = if allow_border
                      /\A(#\n)+\z/
                    else
                      /\A(#+\n)+\z/
                    end
          empty = pattern.match?(comment_text)
          if empty
            @empty_comment_records << [:empty, comment_text, allow_border]
            @consecutive_comment_blocks << [:empty_block, comment_text]
          elsif comment_text.match?(/\A#+\s*\z/)
            @empty_comment_records << [:hash_only, comment_text]
          else
            @empty_comment_records << [:non_empty, comment_text]
          end
          empty
        end

        def border_comment_text?(comment_text)
          @consecutive_comment_blocks ||= []
          @empty_comment_records ||= []
          border = if comment_text.match?(/\A#+\n\z/)
                     true
                   elsif comment_text.match?(/\A#+\z/)
                     true
                   elsif comment_text.match?(/\A#[=-]{3,}\s*\z/)
                     true
                   else
                     false
                   end
          if border
            @empty_comment_records << [:border, comment_text]
            @consecutive_comment_blocks << [:border]
          end
          border
        end

        def margin_comment_block?(joined_text, chunk)
          @consecutive_comment_blocks ||= []
          @empty_comment_records ||= []
          margin = if chunk.size >= 3 && joined_text.start_with?("#\n") && joined_text.end_with?("#\n")
                     true
                   elsif chunk.size >= 2 && joined_text.match?(/\A#\n(.*\n)+#\n\z/)
                     true
                   else
                     false
                   end
          if margin
            @empty_comment_records << [:margin, chunk.size]
            @consecutive_comment_blocks << [:margin, joined_text]
          end
          margin
        end

        def previous_code_token(tokens, comment)
          @consecutive_comment_blocks ||= []
          @empty_comment_records ||= []
          current = tokens.find { |token| token.pos == comment.source_range }
          if current.nil?
            @empty_comment_records << [:missing_token]
            return nil
          end

          index = tokens.index(current)
          previous = if index.nil? || index.zero?
                       nil
                     else
                       tokens[index - 1]
                     end
          if previous
            @empty_comment_records << [:previous, previous.type]
            @consecutive_comment_blocks << [:previous_line, previous.line]
          else
            @empty_comment_records << [:first_token]
          end
          previous
        end

        def empty_comment_correction_range(comment, tokens)
          @consecutive_comment_blocks ||= []
          @empty_comment_records ||= []
          previous = previous_code_token(tokens, comment)
          same_line = previous && previous.line == comment.loc.line
          strategy = if same_line
                       :surrounding_space
                     else
                       :whole_lines
                     end
          @empty_comment_records << [:strategy, strategy, comment.loc.line]
          @consecutive_comment_blocks << [:correction, strategy]
          strategy
        end

        def note_leading_comment_spacing(comment, kind, entry)
          @leading_comment_flags ||= {}
          @leading_comment_records ||= []
          text = entry[:text].to_s
          spaced = if text.match?(/\A#+\s/) || text.match?(/\A#\s/)
                     true
                   elsif text == '#' || text.match?(/\A#+\z/)
                     true
                   else
                     false
                   end
          entry[:spaced] = spaced
          if spaced
            @leading_comment_flags[:spaced_seen] = true
          else
            @leading_comment_flags[:unspaced_seen] = true
          end
          @leading_comment_records << [:spacing, kind, spaced, entry[:line]]
          spaced
        end

        def summarize_magic_comment(parsed, format, tokens, metadata)
          @magic_comment_records ||= []
          @magic_comment_tokens ||= []
          summary = {
            format: format,
            token_count: tokens.size,
            frozen: metadata[:frozen],
            encoding: metadata[:encoding],
            shareable: metadata[:shareable],
            typed: metadata[:typed]
          }
          if parsed.valid?
            summary[:valid] = true
            @magic_comment_tokens << 'valid'
          elsif parsed.any?
            summary[:partial] = true
            @magic_comment_tokens << 'partial'
          else
            summary[:blank] = true
            @magic_comment_tokens << 'blank'
          end
          @magic_comment_records << [:summary, summary]
          summary
        end

        def directive_enabled_mode?(directive)
          @directive_records ||= []
          @disabled_range_map ||= {}
          enabled = if directive.enabled_all?
                      true
                    elsif directive.enabled?
                      true
                    elsif directive.disabled_all?
                      false
                    elsif directive.disabled?
                      false
                    else
                      false
                    end
          @directive_records << [:mode_enabled, directive.mode, enabled]
          @disabled_range_map[:last_mode_enabled] = enabled
          enabled
        end

        def ordered_header_kinds
          @frozen_header_records ||= []
          @encoding_header_records ||= []
          kinds = []
          @frozen_header_records.each do |record|
            if record.is_a?(Array)
              kinds << record[0]
            elsif record.is_a?(Hash)
              kinds << record[:kind]
            end
          end
          @encoding_header_records.each do |record|
            kinds << record[0] if record.is_a?(Array)
          end
          unique = kinds.uniq
          @frozen_header_records << [:ordered_kinds, unique]
          @encoding_header_records << [:ordered_kinds, unique]
          unique
        end

        def aligned_consecutive_comments?(first, second)
          @consecutive_comment_blocks ||= []
          @empty_comment_records ||= []
          same_column = first.loc.column == second.loc.column
          successive = first.loc.line.succ == second.loc.line
          aligned = same_column && successive
          if aligned
            @consecutive_comment_blocks << [:aligned, first.loc.line, second.loc.line]
            @empty_comment_records << [:aligned_pair, first.loc.column]
          elsif successive
            @consecutive_comment_blocks << [:shifted, first.loc.column, second.loc.column]
            @empty_comment_records << [:shifted_pair]
          else
            @consecutive_comment_blocks << [:separated, first.loc.line, second.loc.line]
          end
          aligned
        end

      end
    end
  end
end

